import{_ as t,o as s,c as i,a2 as o}from"./chunks/framework.BXzK3EA4.js";const a="/assets/image%20(82).CZFAN8cu.png",g=JSON.parse('{"title":"SSL Verification Failed","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/windows-installation/ssl-verification-failed.md","filePath":"getting-started/windows-installation/ssl-verification-failed.md"}'),n={name:"getting-started/windows-installation/ssl-verification-failed.md"};function r(l,e,d,p,h,c){return s(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="ssl-verification-failed" tabindex="-1">SSL Verification Failed <a class="header-anchor" href="#ssl-verification-failed" aria-label="Permalink to &quot;SSL Verification Failed&quot;">​</a></h1><p>If you’ve encountered the SSL: CERTIFICATE_VERIFY_FAILED error while using Tradeboard on Windows, there’s good news. A user from the Tradeboard community has shared a comprehensive solution that resolved this issue on their Windows system. Here’s a detailed guide on how to implement this solution.</p><p><strong>Understanding the Issue</strong></p><p>The SSL: CERTIFICATE_VERIFY_FAILED error usually indicates that the SSL certificate presented by the server cannot be verified by the client. This can happen due to several reasons, including outdated or missing root certificates on your system.</p><p><strong>Proposed Solution</strong></p><p>A user successfully resolved this issue by updating the root certificates on their Windows system. The solution involves using the certutil tool to update and install root certificates. Here are the detailed steps:</p><p><strong>1. Update Certificates Using Certutil</strong></p><p>First, you need to update the root certificates on your Windows system. Follow these steps using Command Prompt with administrative access:</p><p>1. <strong>Open Command Prompt with Admin Access</strong>: Right-click on the Command Prompt icon and select “Run as administrator”.</p><figure><img src="'+a+'" alt=""><figcaption></figcaption></figure><p>2. <strong>Generate Root Certificates File</strong>: Run the following command to generate the root certificates file.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">certutil</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -generateSSTFromWU</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> roots.sst</span></span></code></pre></div><p><br> 3. <strong>Install Root Certificates</strong>: Once the roots.sst file is generated, run the following command to install the certificates.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">certutil</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -addstore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> roots.sst</span></span></code></pre></div><p><strong>2. Verify and Reinstall</strong></p><p>After updating the root certificates, you can verify if the issue is resolved by running your Tradeboard application. Here’s an additional step-by-step verification process shared by the user:</p><p>1. <strong>Uninstall Existing Python Installation</strong>: If you still face issues, uninstall the existing Python installation.</p><p>2. <strong>Reboot the Server</strong>: Reboot your Windows system to ensure all changes take effect.</p><p>3. <strong>Install a Current Python Version</strong>: Download and install Python 3.12 or newer, which is the minimum Tradeboard supports (for example <code>python-3.12.x-amd64</code>). Tick &quot;Add python.exe to PATH&quot; during the install.</p><p>4. <strong>Run Tradeboard Application</strong>: Run your Tradeboard application to verify if the SSL error is resolved.</p><p>By updating the root certificates using certutil and ensuring that your system has the latest Python installation, you can resolve the SSL: CERTIFICATE_VERIFY_FAILED error on Windows systems. This method has been tested and confirmed to work by couple of users in the Tradeboard community.</p><p>For more details and context, you can refer to <a href="https://github.com/wesoftcorp/tradeboard-docs/issues/43" target="_blank" rel="noreferrer">this issue on GitHub</a>.</p><p>If you’re encountering SSL-related errors on Windows, give these Command Prompt actions a try. Your feedback and experiences are valuable, so feel free to share them in the comments below. Happy coding with Tradeboard!</p>',23)])])}const f=t(n,[["render",r]]);export{g as __pageData,f as default};
